create table erp.voucher_lines (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default app.current_org_id() references core.organizations(id) on delete cascade,
  branch_id uuid default erp.my_branch_id(),
  voucher_id uuid not null,
  account_id uuid not null,
  debit numeric(14,2) not null default 0,
  credit numeric(14,2) not null default 0,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, voucher_id) references erp.vouchers(org_id, id) on delete restrict,
  foreign key (org_id, account_id) references erp.accounts(org_id, id) on delete restrict,
  check (debit >= 0 and credit >= 0 and (debit > 0) <> (credit > 0))
);
create index voucher_lines_branch on erp.voucher_lines(org_id, branch_id);
create index voucher_lines_voucher_id on erp.voucher_lines(org_id, voucher_id);
create index voucher_lines_account_id on erp.voucher_lines(org_id, account_id);
create trigger trg_touch before update on erp.voucher_lines for each row execute function app.touch_updated_at();
select app.apply_rls(p_schema => 'erp', p_table => 'voucher_lines', p_kind => 'product', p_product => 'erp', p_module => 'accounting');
drop policy del on erp.voucher_lines;
create trigger trg_immutable before update or delete on erp.voucher_lines for each row execute function erp.immutable_rows('', '');
comment on table erp.voucher_lines is 'erp product data (generated by scripts/gen-erp.mjs). module: accounting';

create table erp.expenses (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default app.current_org_id() references core.organizations(id) on delete cascade,
  branch_id uuid default erp.my_branch_id(),
  description text not null,
  date date not null default current_date,
  account_id uuid,
  vendor_id uuid,
  amount numeric(14,2) not null,
  bill_no text,
  status text not null default 'requested' check (status in ('requested', 'approved', 'paid', 'rejected')),
  payment_mode text not null default 'bank_transfer' check (payment_mode in ('cash', 'bank_transfer', 'cheque', 'upi')),
  is_petty_cash boolean not null default false,
  requested_by uuid default app.uid(),
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, account_id) references erp.accounts(org_id, id) on delete set null (account_id),
  foreign key (org_id, vendor_id) references erp.vendors(org_id, id) on delete set null (vendor_id),
  foreign key (org_id, requested_by) references core.org_users(org_id, user_id) on delete set null (requested_by)
);
create index expenses_branch on erp.expenses(org_id, branch_id);
create index expenses_account_id on erp.expenses(org_id, account_id);
create index expenses_vendor_id on erp.expenses(org_id, vendor_id);
