create trigger trg_touch before update on erp.expenses for each row execute function app.touch_updated_at();
select app.apply_rls(p_schema => 'erp', p_table => 'expenses', p_kind => 'product', p_product => 'erp', p_module => 'accounting');
create policy sel_own on erp.expenses for select using (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and requested_by = app.uid());
create policy ins_own on erp.expenses for insert with check (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and requested_by = app.uid() and app.my_member_kind() in ('staff','support') and (status = 'requested'));
comment on table erp.expenses is 'erp product data (generated by scripts/gen-erp.mjs). module: accounting';

